@Provides
@HandlerPriority(-1025) //HandleBuilder's level, minus one.
public class HandleBuilderDefault extends JavacAnnotationHandler<Builder.Default> {
	private final String defaultProviderPrefix = HandleBuilder.DEFAULT_PREFIX;

	public JCMethodDecl generateDefaultProvider(BuilderJob job, BuilderFieldData bfd, JavacNode fieldNode) {
		JavacTreeMaker maker = fieldNode.getAst().getTreeMaker();
		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		JavacNode parentType = job.parentType;
		JCClassDecl classDecl = (JCClassDecl) parentType.get();

		Name defaultName = parentType.toName(this.defaultProviderPrefix + bfd.name);
		Name setFlagName = parentType.toName(bfd.name + HandleBuilder.SET_PREFIX);
		Name valueName = parentType.toName(bfd.name + HandleBuilder.VALUE_PREFIX);
		bfd.nameOfDefaultProvider = defaultName;
		bfd.nameOfSetFlag = setFlagName;
		bfd.builderFieldName = valueName;

		JCStatement statement = maker.Return(field.init);
		field.init = null;

		java.util.Map<com.sun.tools.javac.tree.JCTree, Integer> posMap = capturePositions(statement);

		JCBlock body = maker.Block(0, List.<JCStatement>of(statement));
		int modifiers = Flags.PRIVATE | Flags.STATIC;
		JCMethodDecl methodDecl = maker.MethodDef(maker.Modifiers(modifiers), defaultName, cloneType(maker, field.vartype, fieldNode), copyTypeParams(fieldNode, classDecl.typarams), List.<JCVariableDecl>nil(), List.<JCExpression>nil(), body, null);
		recursiveSetGeneratedBy(methodDecl, job.sourceNode);
		restorePositions(posMap);
		if (methodDecl != null) injectMethod(parentType, methodDecl);
		return methodDecl;
	}

	private static java.util.Map<com.sun.tools.javac.tree.JCTree, Integer> capturePositions(com.sun.tools.javac.tree.JCTree tree) {
		java.util.Map<com.sun.tools.javac.tree.JCTree, Integer> posMap = new java.util.IdentityHashMap<com.sun.tools.javac.tree.JCTree, Integer>();
		capturePositions(tree, posMap);
		return posMap;
	}

	private static void capturePositions(final com.sun.tools.javac.tree.JCTree tree, final java.util.Map<com.sun.tools.javac.tree.JCTree, Integer> posMap) {
		if (tree == null) return;
		posMap.put(tree, tree.pos);
		tree.accept(new com.sun.tools.javac.tree.TreeScanner() {
			@Override public void scan(com.sun.tools.javac.tree.JCTree t) {
				if (t == null) return;
				capturePositions(t, posMap);
			}
		});
	}

	private static void restorePositions(java.util.Map<com.sun.tools.javac.tree.JCTree, Integer> posMap) {
		for (java.util.Map.Entry<com.sun.tools.javac.tree.JCTree, Integer> e : posMap.entrySet()) {
			e.getKey().pos = e.getValue();
		}
	}

	@Override public void handle(AnnotationValues<Builder.Default> annotation, JCAnnotation ast, JavacNode annotationNode) {
		JavacNode annotatedField = annotationNode.up();
		if (annotatedField.getKind() != Kind.FIELD) return;
		JavacNode classWithAnnotatedField = annotatedField.up();
		if (!hasAnnotation(Builder.class, classWithAnnotatedField) && !hasAnnotation("lombok.experimental.Builder", classWithAnnotatedField)
				&& !hasAnnotation(SuperBuilder.class, classWithAnnotatedField)) {
			annotationNode.addWarning("@Builder.Default requires @Builder or @SuperBuilder on the class for it to mean anything.");
			deleteAnnotationIfNeccessary(annotationNode, Builder.Default.class);
		}

		/** HandleBuilder is going to wipe out the import, at which point '@Builder.Default' is no longer clear. */
		if (ast.annotationType instanceof JCFieldAccess) {
			JCFieldAccess jfa = (JCFieldAccess) ast.annotationType;
			if (jfa.selected instanceof JCIdent && ((JCIdent) jfa.selected).name.contentEquals("Builder") && jfa.name.contentEquals("Default")) {
				JCFieldAccess newJfaSel = annotationNode.getTreeMaker().Select(annotationNode.getTreeMaker().Ident(annotationNode.toName("lombok")), ((JCIdent) jfa.selected).name);
				recursiveSetGeneratedBy(newJfaSel, annotationNode);
				jfa.selected = newJfaSel;
			}
		}

