/**
 * Takes note of the position of every node in the given tree, so that these positions can be put back after
 * {@link JavacHandlerUtil#recursiveSetGeneratedBy} has stamped the source node's position onto all of them.
 * Repositioning the (user-written) initializing expression of the field is a problem, because javac caches the
 * type of method invocation expressions based on position; see also the comment in HandleBuilder's toBuilder()
 * handling of {@code @ObtainVia}. If every method invocation in the initializer ends up with the same position,
 * javac mixes up their types. Furthermore, error messages would point at the {@code @Builder} annotation instead
 * of the expression that caused the problem.
 */
private static class PositionPreserver extends TreeScanner {
	private final Map<JCTree, Integer> positions = new IdentityHashMap<JCTree, Integer>();

	PositionPreserver(JCTree tree) {
		scan(tree);
	}

	@Override public void scan(JCTree tree) {
		if (tree == null) return;
		positions.put(tree, tree.pos);
		super.scan(tree);
	}

	void restore() {
		for (Map.Entry<JCTree, Integer> entry : positions.entrySet()) entry.getKey().pos = entry.getValue();
	}
}

