private static class PositionPreserver extends TreeScanner {
	private final Map<JCTree, Integer> positions = new IdentityHashMap<JCTree, Integer>();
	private final Map<JCTree, Integer> endPositions = new IdentityHashMap<JCTree, Integer>();
	private final JCCompilationUnit cu;

	PositionPreserver(JCTree tree, JCCompilationUnit cu) {
		this.cu = cu;
		scan(tree);
	}

	@Override public void scan(JCTree tree) {
		if (tree == null) return;
		positions.put(tree, tree.pos);
		int endPos = Javac.getEndPosition(tree, cu);
		if (endPos != -1) endPositions.put(tree, endPos);
		super.scan(tree);
	}

	void restore() {
		for (Map.Entry<JCTree, Integer> entry : positions.entrySet()) entry.getKey().pos = entry.getValue();
		for (Map.Entry<JCTree, Integer> entry : endPositions.entrySet()) Javac.storeEnd(entry.getKey(), entry.getValue(), cu);
	}
}

